INSERT INTO "PUBLIC"."GENERATED_ARTIFACTS" VALUES
(318, 'MARKDOWN', U&'# Architecture\000a\000aLayered Spring Boot application with relational persistence\000a\000a## Components\000a- **UrlShortenerController**: Thin REST layer\000a- **UrlShortenerService**: Business rules and transactions\000a- **ShortUrlRepository / UrlClickRepository**: Spring Data JPA persistence\000a\000a## Decisions\000a- AD-1 Layered Spring Boot monolith - Smallest operational footprint that meets the requirement (alternatives: Microservices)\000a- AD-2 Base62 random codes with DB unique constraint - Collision-resistant and non-enumerable; the constraint is the source of truth (alternatives: Sequential ids encoded in base62)\000a', TIMESTAMP WITH TIME ZONE '2026-11-08 07:48:25.018151+00', 'architecture.md', '9fa40058e2271ebea1bb67e4384e8086c75827699bb187e98b721dbfe7be352a', 'STAGED', NULL, 'c3ffedb3-b101-49a5-8316-15cd070b1f72/v1/architecture.md', 'architecture', 1, 'c3ffedb3-b101-49a5-8316-15cd070b1f72'),
(319, 'MARKDOWN', U&'# Test plan\000a\000aTest pyramid: unit for rules, integration for APIs\000a\000a| Id | Type | Name | Covers |\000a|---|---|---|---|\000a| TC-1 | INTEGRATION | Verifies AC-1 | [AC-1] |\000a| TC-2 | INTEGRATION | Verifies AC-2 | [AC-2] |\000a| TC-3 | INTEGRATION | Verifies AC-3 | [AC-3] |\000a| TC-4 | INTEGRATION | Verifies AC-4 | [AC-4] |\000a| TC-5 | INTEGRATION | Verifies AC-5 | [AC-5] |\000a| TC-6 | UNIT | Verifies AC-6 | [AC-6] |\000a| TC-7 | UNIT | Rejects blank and malformed input | [] |\000a\000aCriteria coverage: 100%\000a', TIMESTAMP WITH TIME ZONE '2026-11-08 07:48:25.033869+00', 'test-plan.md', 'a8d82350e192e335ae6babe76262737a1a729a0d318d69314d979e85a3458b56', 'STAGED', NULL, 'c3ffedb3-b101-49a5-8316-15cd070b1f72/v1/test-plan.md', 'test-planning', 1, 'c3ffedb3-b101-49a5-8316-15cd070b1f72'),
