INSERT INTO "PUBLIC"."GENERATED_ARTIFACTS" VALUES
(572, 'MARKDOWN', U&'# Architecture\000a\000aLayered Spring Boot application with relational persistence\000a\000a## Components\000a- **UrlShortenerController**: Thin REST layer\000a- **UrlShortenerService**: Business rules and transactions\000a- **ShortUrlRepository / UrlClickRepository**: Spring Data JPA persistence\000a\000a## Decisions\000a- AD-1 Layered Spring Boot monolith - Smallest operational footprint that meets the requirement (alternatives: Microservices)\000a- AD-2 Base62 random codes with DB unique constraint - Collision-resistant and non-enumerable; the constraint is the source of truth (alternatives: Sequential ids encoded in base62)\000a', TIMESTAMP WITH TIME ZONE '2026-11-08 07:49:36.578968+00', 'architecture.md', '9fa40058e2271ebea1bb67e4384e8086c75827699bb187e98b721dbfe7be352a', 'STAGED', NULL, 'b9dd7f6c-8e7a-4216-bf21-c167be460b8a/v1/architecture.md', 'architecture', 1, 'b9dd7f6c-8e7a-4216-bf21-c167be460b8a'),
