INSERT INTO "PUBLIC"."WORKFLOW_TASKS" VALUES
(1, 'requirement', NULL, 1, TIMESTAMP WITH TIME ZONE '2026-11-08 07:45:50.768644+00', NULL, NULL, NULL, 'requirements', 'AGENT', '{"scenario":"GREENFIELD","summary":"Build a URL shortener with custom aliases, expiration, redirects and click analytics.","normalizedRequirement":"Build a URL shortener that supports custom aliases, expiration, redirects, and click analytics.","functionalRequirements":[{"id":"FR-1","text":"Create short URLs from valid http/https URLs"},{"id":"FR-2","text":"Redirect a short code to the original URL"},{"id":"FR-3","text":"Support unique custom aliases"},{"id":"FR-4","text":"Support expiration dates"},{"id":"FR-5","text":"Track clicks with timestamps and referrer, and expose analytics"}],"nonFunctionalRequirements":[{"id":"NFR-1","text":"Only http/https targets (open-redirect prevention)","target":"100% of other schemes rejected"},{"id":"NFR-2","text":"Redirect path should avoid unnecessary DB calls","target":"<= 3 statements per redirect"}],"acceptanceCriteria":[{"id":"AC-1","text":"Given a valid URL, POST /api/v1/urls returns 201 and a unique collision-resistant code","requirementId":"FR-1","testType":"INTEGRATION","status":"AGREED"},{"id":"AC-2","text":"Given an active, unexpired code, GET returns 302 with the original URL","requirementId":"FR-2","testType":"INTEGRATION","status":"AGREED"},{"id":"AC-3","text":"Given a free alias it is used; a duplicate alias returns 409","requirementId":"FR-3","testType":"INTEGRATION","status":"AGREED"},{"id":"AC-4","text":"Given an expired link, redirect returns 410 and past dates are rejected on creation","requirementId":"FR-4","testType":"INTEGRATION","status":"AGREED"},{"id":"AC-5","text":"Each redirect increments the click count; analytics returns totals, referrers and daily clicks","requirementId":"FR-5","testType":"INTEGRATION","status":"AGREED"},{"id":"AC-6","text":"javascript:, data: and file: URLs are rejected with 400","requirementId":"NFR-1","testType":"UNIT","status":"AGREED"}],"ambiguities":[{"id":"AMB-1","topic":"Alias rules","severity":"MINOR","question":"Allowed alias length and characters?","provisionalAssumption":"3-32 chars of [A-Za-z0-9_-]"},{"id":"AMB-2","topic":"Expiration timezone","severity":"MINOR","question":"Which timezone applies to expiration dates?","provisionalAssumption":"UTC"},{"id":"AMB-3","topic":"Redirect status code","severity":"MINOR","question":"301 or 302?","provisionalAssumption":"302 so every click is counted"}],"clarificationQuestions":[{"id":"AMB-1","severity":"MINOR","question":"Allowed alias length and characters?"},{"id":"AMB-2","severity":"MINOR","question":"Which timezone applies to expiration dates?"},{"id":"AMB-3","severity":"MINOR","question":"301 or 302?"}],"provisionalAssumptions":["AMB-1: 3-32 chars of [A-Za-z0-9_-]","AMB-2: UTC","AMB-3: 302 so every click is counted","Single region, relational database, no authentication on the public redirect."],"missingInformation":[],"blockingAmbiguity":false,"_execution":{"degraded":false,"attempts":1,"fallbackUsed":false,"provider":"mock-llm"}}', '{}', 1, 'REQUIREMENT_UNDERSTANDING', TIMESTAMP WITH TIME ZONE '2026-11-08 07:45:50.654143+00', 'COMPLETED', 'Requirement understanding', TIMESTAMP WITH TIME ZONE '2026-11-08 07:45:50.768644+00', '9238ae18-9655-4f05-b190-70151db47ec1'),
(2, NULL, 'MATERIAL_ASSUMPTIONS', 0, TIMESTAMP WITH TIME ZONE '2026-11-08 07:45:50.820176+00', 'requirements.blockingAmbiguity == true', NULL, NULL, 'assumption-approval', 'APPROVAL', '{"reason":"condition not met: requirements.blockingAmbiguity == true","skipped":true}', '{}', 1, 'REQUIREMENT_UNDERSTANDING', NULL, 'SKIPPED', 'Approve material assumptions', TIMESTAMP WITH TIME ZONE '2026-11-08 07:45:50.820176+00', '9238ae18-9655-4f05-b190-70151db47ec1'),
(3, 'planning', NULL, 1, TIMESTAMP WITH TIME ZONE '2026-11-08 07:45:50.901855+00', NULL, NULL, NULL, 'planning', 'AGENT', '{"tasks":[{"id":"T1","title":"Project skeleton and configuration","category":"SETUP","estimateHours":2,"dependsOn":[]},{"id":"T2","title":"Data model and constraints","category":"IMPLEMENTATION","estimateHours":3,"dependsOn":["T1"]},{"id":"T3","title":"Short code generator","category":"IMPLEMENTATION","estimateHours":2,"dependsOn":["T1"]},{"id":"T4","title":"Create-URL API with validation","category":"IMPLEMENTATION","estimateHours":4,"dependsOn":["T2","T3"]},{"id":"T5","title":"Redirect endpoint","category":"IMPLEMENTATION","estimateHours":3,"dependsOn":["T2"]},{"id":"T6","title":"Custom alias handling","category":"IMPLEMENTATION","estimateHours":2,"dependsOn":["T4"]},{"id":"T7","title":"Expiration handling","category":"IMPLEMENTATION","estimateHours":2,"dependsOn":["T4","T5"]},{"id":"T8","title":"Click tracking and analytics API","category":"IMPLEMENTATION","estimateHours":5,"dependsOn":["T5"]},{"id":"T9","title":"Error handling and OpenAPI","category":"IMPLEMENTATION","estimateHours":2,"dependsOn":["T4","T5"]},{"id":"T10","title":"Automated tests","category":"TESTING","estimateHours":6,"dependsOn":["T9"]}],"taskGraph":[{"from":"T1","to":"T2"},{"from":"T1","to":"T3"},{"from":"T2","to":"T4"},{"from":"T3","to":"T4"},{"from":"T2","to":"T5"},{"from":"T4","to":"T6"},{"from":"T4","to":"T7"},{"from":"T5","to":"T7"},{"from":"T5","to":"T8"},{"from":"T4","to":"T9"},{"from":"T5","to":"T9"},{"from":"T9","to":"T10"}],"topologicalOrder":["T1","T2","T3","T5","T4","T8","T6","T7","T9","T10"],"parallelGroups":[["T1"],["T2","T3"],["T5","T4"],["T8","T6","T7","T9"],["T10"]],"criticalPath":["T1","T2","T4","T9","T10"],"criticalPathHours":17,"taskCount":10,"assumptionsApplied":[],"_execution":{"degraded":false,"attempts":1,"fallbackUsed":false,"provider":"mock-llm"}}', '{}', 1, 'TASK_DECOMPOSITION', TIMESTAMP WITH TIME ZONE '2026-11-08 07:45:50.85031+00', 'COMPLETED'